import React, { useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { GoogleLogin } from '@react-oauth/google'
import { useAuth } from '../providers/auth'

const Auth = () => {
  const navigate = useNavigate()
  const { login, register, loginWithGoogleCredential } = useAuth()

  const [isLogin, setIsLogin] = useState(true)
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    password: '',
  })
  const [error, setError] = useState('')

  const handleInputChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value,
    })
  }

  // Handle Standard Email & Password Form Submission
  const handleSubmit = (e) => {
    e.preventDefault()
    setError('')

    try {
      if (isLogin) {
        const res = login(formData.email, formData.password)
        if (res?.success) navigate('/')
      } else {
        const res = register(formData.email, formData.password, formData.name)
        if (res?.success) navigate('/')
      }
    } catch (err) {
      setError(err.message || 'Authentication failed. Please try again.')
    }
  }

  // Google Sign-In Success Handler
  const handleGoogleSuccess = (credentialResponse) => {
    try {
      if (credentialResponse?.credential) {
        loginWithGoogleCredential(credentialResponse.credential)
        navigate('/')
      } else {
        setError('Google sign-in failed. No credentials returned.')
      }
    } catch (err) {
      console.error('Google Auth Error:', err)
      setError(err.message || 'Google sign-in failed.')
    }
  }

  // Google Sign-In Error Handler
  const handleGoogleError = () => {
    setError('Google sign-in popup was closed or failed.')
  }

  // Explicit definition for handleGoogleSignIn (if triggered directly by custom button)
  const handleGoogleSignIn = () => {
    setError('Please click the Google button below to sign in.')
  }

  return (
    <div style={styles.container}>
      <div style={styles.card}>
        <h2 style={styles.title}>{isLogin ? 'Welcome Back' : 'Create Account'}</h2>
        <p style={styles.subtitle}>
          {isLogin ? 'Sign in to access your video rooms' : 'Get started with AuraChat'}
        </p>

        {error && <div style={styles.errorBanner}>{error}</div>}

        {/* Google OAuth Login Button */}
        <div style={styles.googleBtnContainer}>
          <GoogleLogin
            onSuccess={handleGoogleSuccess}
            onError={handleGoogleError}
            theme="filled_blue"
            size="large"
            width="100%"
          />
        </div>

        <div style={styles.divider}>
          <span style={styles.dividerText}>OR</span>
        </div>

        {/* Form for Local Login / Register */}
        <form onSubmit={handleSubmit} style={styles.form}>
          {!isLogin && (
            <div style={styles.inputGroup}>
              <label style={styles.label}>Name</label>
              <input
                type="text"
                name="name"
                value={formData.name}
                onChange={handleInputChange}
                placeholder="Enter your name"
                required={!isLogin}
                style={styles.input}
              />
            </div>
          )}

          <div style={styles.inputGroup}>
            <label style={styles.label}>Email</label>
            <input
              type="email"
              name="email"
              value={formData.email}
              onChange={handleInputChange}
              placeholder="Enter your email"
              required
              style={styles.input}
            />
          </div>

          <div style={styles.inputGroup}>
            <label style={styles.label}>Password</label>
            <input
              type="password"
              name="password"
              value={formData.password}
              onChange={handleInputChange}
              placeholder="Enter your password"
              required
              style={styles.input}
            />
          </div>

          <button type="submit" style={styles.submitBtn}>
            {isLogin ? 'Sign In' : 'Sign Up'}
          </button>
        </form>

        <p style={styles.toggleText}>
          {isLogin ? "Don't have an account? " : 'Already have an account? '}
          <span
            onClick={() => {
              setIsLogin(!isLogin)
              setError('')
            }}
            style={styles.toggleLink}
          >
            {isLogin ? 'Sign Up' : 'Sign In'}
          </span>
        </p>
      </div>
    </div>
  )
}

// Inline Styles (Clean & Responsive)
const styles = {
  container: {
    display: 'flex',
    justifyContent: 'center',
    alignItems: 'center',
    minHeight: '100vh',
    backgroundColor: '#f5f7fb',
    padding: '20px',
    boxSizing: 'border-box',
  },
  card: {
    width: '100%',
    maxWidth: '400px',
    padding: '32px',
    backgroundColor: '#ffffff',
    borderRadius: '12px',
    boxShadow: '0 4px 20px rgba(0,0,0,0.08)',
    textAlign: 'center',
  },
  title: {
    margin: '0 0 8px 0',
    color: '#1a1a1a',
    fontSize: '24px',
    fontWeight: '600',
  },
  subtitle: {
    color: '#666666',
    fontSize: '14px',
    marginBottom: '24px',
    marginTtop: 0,
  },
  errorBanner: {
    backgroundColor: '#ffebe9',
    color: '#d93025',
    padding: '10px 14px',
    borderRadius: '6px',
    fontSize: '13px',
    marginBottom: '16px',
    border: '1px solid #f8c4b7',
  },
  googleBtnContainer: {
    display: 'flex',
    justifyContent: 'center',
    marginBottom: '20px',
    width: '100%',
  },
  divider: {
    display: 'flex',
    alignItems: 'center',
    textAlign: 'center',
    margin: '20px 0',
    borderBottom: '1px solid #e0e0e0',
    lineHeight: '0.1em',
  },
  dividerText: {
    backgroundColor: '#fff',
    padding: '0 10px',
    color: '#888',
    fontSize: '12px',
    margin: '0 auto',
  },
  form: {
    display: 'flex',
    flexDirection: 'column',
    gap: '16px',
    textAlign: 'left',
  },
  inputGroup: {
    display: 'flex',
    flexDirection: 'column',
    gap: '6px',
  },
  label: {
    fontSize: '13px',
    fontWeight: '500',
    color: '#333333',
  },
  input: {
    padding: '10px 14px',
    borderRadius: '6px',
    border: '1px solid #cccccc',
    fontSize: '14px',
    outline: 'none',
  },
  submitBtn: {
    padding: '12px',
    borderRadius: '6px',
    border: 'none',
    backgroundColor: '#1a73e8',
    color: '#ffffff',
    fontSize: '15px',
    fontWeight: '600',
    cursor: 'pointer',
    marginTop: '8px',
  },
  toggleText: {
    marginTop: '24px',
    fontSize: '14px',
    color: '#555555',
    marginBottom: 0,
  },
  toggleLink: {
    color: '#1a73e8',
    cursor: 'pointer',
    fontWeight: '600',
  },
}

export default Auth
